				"text": "' VB style self test - each check prints its number and ok or FAIL\nOption PressAnyKeyOnEnd \"Press a key\"     ' at the end: a message and a key (a RUN\" program resets when it ends)\nOption Explicit\n\nConst MAXN = 10\nConst GREETING = \"Hi\"\nConst BIG = MAXN * 100 + 1\n\nType Point\n  x As Integer\n  y As Integer\nEnd Type\n\nDim t As Integer, bad As Integer\nDim i As Integer, j As Integer, s As Integer, n As Integer\nDim a$, b As String, c As String\nDim p As Point, q As Point\nDim pts(3) As Point\nDim names(4) As String\nDim grid(2, 3) As Integer\nDim tk As Integer\n\nCls\nPrint \"VB self test\"\n\n' ---- constants\nChk BIG, 1001\nChkS GREETING & \"!\", \"Hi!\"\n\n' ---- functions and subs\nChk Add(2, 3), 5\nChk Add(Add(1, 2), Add(3, 4)), 10\nChk Twice(21), 42\nn = 5\nBump n\nChk n, 6\nBump n\nChk n, 7\nn = 5\nNoBump n\nChk n, 5\nChk Fact(7), 5040\nChk Counter(), 1\nChk Counter(), 2\nChk Fresh(), 1\nChk Fresh(), 1\nChk Clamp(50), 10\nChk Clamp(-4), 0\nChk Clamp(7), 7\n\n' ---- select case\nChk Grade(95), 1\nChk Grade(85), 2\nChk Grade(70), 3\nChk Grade(3), 4\nChk Kind(\"apple\"), 1\nChk Kind(\"pear\"), 2\nChk Kind(\"zzz\"), 0\n\n' ---- strings\na$ = \"Hello\"\nb = \"World\"\nc = a$ & \", \" & b & \"!\"\nChkS c, \"Hello, World!\"\nChk Len(c), 13\nChkS Left$(c, 5), \"Hello\"\nChkS Right$(c, 6), \"World!\"\nChkS Mid$(c, 8, 5), \"World\"\nChkS Mid$(c, 8), \"World!\"\nChkS UCase$(a$), \"HELLO\"\nChkS LCase(b), \"world\"\nChkS Chr$(65) & Chr$(66), \"AB\"\nChk Asc(\"A\"), 65\nChkS Str$(42), \" 42\"\nChkS Str$(-7), \"-7\"\nChkS \"n=\" & 12, \"n=12\"\nChk Val(\"123\"), 123\nChk Val(\" -45\"), -45\nChk Val(\"&HFF\"), 255\nChk InStr(c, \"World\"), 8\nChk InStr(c, \"xyz\"), 0\nChk InStr(9, c, \"o\"), 9\nChkS Trim$(\"  ab  \"), \"ab\"\nChkS LTrim$(\"  ab\"), \"ab\"\nChkS RTrim$(\"ab  \") & \"|\", \"ab|\"\nChkS Space$(3) & \"x\", \"   x\"\nChkS String$(4, \"*\"), \"****\"\nChkS Hex$(255), \"FF\"\nn = 4096\nChkS Hex$(n), \"1000\"\nc = \"abc\"\nc = c & c\nChkS c, \"abcabc\"\nChk (\"abc\" < \"abd\"), -1\nChk (\"b\" > \"abc\"), -1\nChk (\"abc\" <= \"abc\"), -1\nn = 9\nChkS \"x\" & n & \"y\", \"x9y\"\n\n' ---- types and arrays\np.x = 3\np.y = 4\nq = p\nChk q.x + q.y, 7\nFor i = 0 To 3\n  pts(i).x = i\n  pts(i).y = i * 10\nNext\ns = 0\nFor i = 0 To 3\n  s = s + pts(i).x + pts(i).y\nNext\nChk s, 66\nnames(0) = \"zero\"\nnames(2) = \"two\"\ni = 2\nChkS names(i) & names(0), \"twozero\"\nnames(i) = names(i) & \"!\"\nChkS names(2), \"two!\"\nFor i = 0 To 2\n  For j = 0 To 3\n    grid(i, j) = i * 10 + j\n  Next\nNext\nChk grid(2, 3), 23\ni = 1\nj = 2\nChk grid(i, j), 12\n\n' ---- turbo switching\nTurbo On\ns = 0\nFor i = 1 To 100\n  s = s + i\nNext\nTurbo Off\nChk s, 5050\ntk = Ticks\nFor i = 1 To 2000\n  s = s + 1\nNext\nChk (Ticks > tk) Or (System.TicksPerSecond = 0), -1   ' no clock on this platform: skip\nChk Sum3(1, 2, 3), 6\nTurbo On\nChk Sum3(4, 5, 6), 15\nTurbo Off\n\nPrint\nPrint t; \" tests, \"; bad; \" failed\"\nEnd\n\nSub Chk(ByVal got As Integer, ByVal want As Integer)\n  t = t + 1\n  Print t; \":\";\n  If got = want Then\n    Print \"ok \";\n  Else\n    Print \"FAIL(\"; got; \") \";\n    bad = bad + 1\n  End If\nEnd Sub\n\nSub ChkS(ByVal got As String, ByVal want As String)\n  t = t + 1\n  Print t; \":\";\n  If got = want Then\n    Print \"ok \";\n  Else\n    Print \"FAIL[\"; got; \"] \";\n    bad = bad + 1\n  End If\nEnd Sub\n\nFunction Add(ByVal x As Integer, ByVal y As Integer) As Integer\n  Add = x + y\nEnd Function\n\nFunction Twice(v As Integer) As Integer\n  Twice = Add(v, v)\nEnd Function\n\nSub Bump(v As Integer)\n  v = v + 1\nEnd Sub\n\nSub NoBump(ByVal v As Integer)\n  v = v + 1\nEnd Sub\n\nFunction Fact(ByVal k As Integer) As Integer\n  Dim r As Integer\n  r = 1\n  Do While k > 1\n    r = r * k\n    k = k - 1\n  Loop\n  Fact = r\nEnd Function\n\nFunction Counter() As Integer\n  Static calls As Integer\n  calls = calls + 1\n  Counter = calls\nEnd Function\n\nFunction Fresh() As Integer\n  Dim calls As Integer\n  calls = calls + 1\n  Fresh = calls\nEnd Function\n\nFunction Clamp(ByVal v As Integer) As Integer\n  Clamp = v\n  If v > MAXN Then\n    Clamp = MAXN\n    Exit Function\n  End If\n  If v < 0 Then Clamp = 0\nEnd Function\n\nFunction Grade(ByVal score As Integer) As Integer\n  Select Case score\n    Case Is >= 90\n      Grade = 1\n    Case 80 To 89\n      Grade = 2\n    Case 60, 65, 70, 75\n      Grade = 3\n    Case Else\n      Grade = 4\n  End Select\nEnd Function\n\nFunction Kind(ByVal f As String) As Integer\n  Select Case f\n    Case \"apple\", \"banana\"\n      Kind = 1\n    Case \"pear\"\n      Kind = 2\n  End Select\nEnd Function\n\nFunction Sum3(ByVal x As Integer, ByVal y As Integer, ByVal z As Integer) As Integer\n  Sum3 = x + y + z\nEnd Function\n"
