				"name": "vb_test_long.bas",
				"text": "' Long (32 bit) self test - each check prints its number and ok or FAIL\nOption PressAnyKeyOnEnd \"Press a key\"     ' at the end: a message and a key (a RUN\" program resets when it ends)\nOption Explicit\n\nConst BIG = 100000\nConst MEGA = BIG * 10\n\nType Account\n  id As Integer\n  balance As Long\nEnd Type\n\nDim t As Integer, bad As Integer\nDim a As Long, b As Long, c As Long\nDim i As Integer, n As Integer\nDim s As String\nDim arr(4) As Long\nDim acc As Account\nDim total&\n\nCls\nPrint \"Long self test\"\n\n' ---- literals and constants\na = 100000\nChkL a, 100000\nChkL BIG, 100000\nChkL MEGA, 1000000\na = -40000\nChkL a, -40000\nChkS Str$(2147483647), \" 2147483647\"\na = &H7FFFFFFF\nChkL a, 2147483647\n\n' ---- arithmetic\na = 70000\nb = 30000\nChkL a + b, 100000\nChkL a - b, 40000\nChkL b - a, -40000\nChkL a * 3, 210000\nChkL a \\ 7, 10000\nChkL a / 7, 10000\nChkL a Mod 9, 7\nChkL -a Mod 9, -7\nChkL a * -2, -140000\nc = a * 300\nChkL c \\ a, 300\nChkL -a, -70000\nChkL Abs(-a), 70000\nChk Sgn(-a), -1\nChk Sgn(a), 1\nc = 0\nChk Sgn(c), 0\nChkL (a And &HFFFF&), 4464\nChkL a Or 1, 70001\nChkL a Xor a, 0\nChkL Not c, -1\n\n' ---- Integer and Long mixed\nn = 1000\na = n\nChkL a, 1000\na = n * 1000&\nChkL a, 1000000\na = CLng(n) * n\nChkL a, 1000000\nn = 300\na = CLng(n) * n + n\nChkL a, 90300\na = 65537\nn = a\nChk n, 1\nChk CInt(a), 1\n\n' ---- compares\na = 100000\nb = 99999\nChk (a > b), -1\nChk (a < b), 0\nChk (a = 100000), -1\nChk (a <> b), -1\nChk (b <= a), -1\nChk (b >= a), 0\nc = -5\nChk (c < 3), -1\nIf a > 50000 Then n = 1 Else n = 2\nChk n, 1\nc = 0\nIf c Then n = 3 Else n = 4\nChk n, 4\n\n' ---- strings\na = 123456\nChkS CStr(a), \"123456\"\nChkS Str$(a), \" 123456\"\nChkS \"a=\" & a, \"a=123456\"\na = -987654\nChkS CStr(a), \"-987654\"\ns = a\nChkS s, \"-987654\"\na = Val(\"1234567\")\nChkL a, 1234567\na = CLng(\"-200000\")\nChkL a, -200000\ns = \"45000\"\na = s\nChkL a, 45000\n\n' ---- arrays, Types, procedures\nFor i = 0 To 4\n  arr(i) = CLng(i) * 100000\nNext\nChkL arr(4), 400000\ni = 3\nChkL arr(i), 300000\narr(i) = arr(i) + 1\nChkL arr(3), 300001\nacc.id = 7\nacc.balance = 250000\nacc.balance = acc.balance * 2\nChkL acc.balance, 500000\nChkL Twice(123456), 246912\na = 5\nAddTo a, 99995\nChkL a, 100000\nChkL Fact(12), 479001600\n\n' ---- For with a Long counter\ntotal = 0\nFor a = 99998 To 100002\n  total = total + a\nNext\nChkL total, 500000\ntotal = 0\nFor a = 300000 To 100000 Step -100000\n  total = total + a\nNext\nChkL total, 600000\n\n' ---- Select Case on a Long\na = 150000\nSelect Case a\n  Case Is < 100000\n    n = 1\n  Case 100000 To 199999\n    n = 2\n  Case Else\n    n = 3\nEnd Select\nChk n, 2\n\nPrint\nPrint t; \" tests, \"; bad; \" failed\"\nEnd\n\nSub ChkL(ByVal got As Long, ByVal want As Long)\n  t = t + 1\n  Print t; \":\";\n  If got = want Then\n    Print \"ok \";\n  Else\n    Print \"FAIL(\"; got; \") \";\n    bad = bad + 1\n  End If\nEnd Sub\n\nSub Chk(ByVal got As Integer, ByVal want As Integer)\n  t = t + 1\n  Print t; \":\";\n  If got = want Then\n    Print \"ok \";\n  Else\n    Print \"FAIL(\"; got; \") \";\n    bad = bad + 1\n  End If\nEnd Sub\n\nSub ChkS(ByVal got As String, ByVal want As String)\n  t = t + 1\n  Print t; \":\";\n  If got = want Then\n    Print \"ok \";\n  Else\n    Print \"FAIL[\"; got; \"] \";\n    bad = bad + 1\n  End If\nEnd Sub\n\nFunction Twice(ByVal v As Long) As Long\n  Twice = v + v\nEnd Function\n\nSub AddTo(x As Long, ByVal y As Long)\n  x = x + y\nEnd Sub\n\nFunction Fact(ByVal k As Integer) As Long\n  Dim r As Long\n  r = 1\n  Do While k > 1\n    r = r * k\n    k = k - 1\n  Loop\n  Fact = r\nEnd Function\n"
